	private class TaskLaunchingTask : Task {

		public TaskLaunchingTask() : base("Slow Modal Task", true, true, true)
    {
		}

		/* @Override */
		public void run(TaskMonitor monitor) {
			postEvent(getName() + " started...");

			sleep(DELAY_FAST);
			try {
				launchTaskFromBackground(new FastModalTask());
			}
			catch (InterruptedException e) {
				throw new RuntimeException(e);
			}

			threadsFinished.countDown();
			postEvent(getName() + " finished.");
		}
	}

	private class SwingBlocker : Runnable {

		private static readonly long REALLY_LONG_SLEEP_THAT_DOESNT_FINISH_MS = 20000;

		private CountDownLatch started = new CountDownLatch(1);

		/* @Override */
		public void run() {
			started.countDown();
			sleep(REALLY_LONG_SLEEP_THAT_DOESNT_FINISH_MS);
		}

		void waitForStart()
    {
			assertTrue("Swing blocker did not start",
				started.await(DEFAULT_WAIT_TIMEOUT, TimeUnit.MILLISECONDS));
		}

	}

